constexpr unsigned CJ_OBJECT_ALIGNMENT_MASK = 7;
constexpr unsigned CJ_DOUBLE_WORD_MASK = 15;
constexpr unsigned CJ_DOUBLE_WORD_ALIGNMENT = 16;
template <typename KeyT, typename ValT> using StdMap = std::unordered_map<KeyT, ValT>;
